package com.tusk.thought.greedy;

/**
 * @author tusk
 * @desc 给定字符串 s 和 t ，判断 s 是否为 t 的子序列。
 * <p>
 * 字符串的一个子序列是原始字符串删除一些（也可以不删除）字符而不改变剩余字符相对位置形成的新字符串。（例如，"ace"是"abcde"的一个子序列，而"aec"不是）。
 * <p>
 * 进阶：
 * <p>
 * 如果有大量输入的 S，称作 S1, S2, ... , Sk 其中 k >= 10亿，你需要依次检查它们是否为 T 的子序列。在这种情况下，你会怎样改变代码？
 * <p>
 * 来源：力扣（LeetCode）
 * 链接：https://leetcode-cn.com/problems/is-subsequence
 * 著作权归领扣网络所有。商业转载请联系官方授权，非商业转载请注明出处。
 * @date 2021/6/7 10:42
 */
public class P392_IsSubsequence {
    public static void main(String[] args) {
        P392_IsSubsequence obj = new P392_IsSubsequence();
        String s = "leeeeetcode";
        String t = "";
        System.out.println(obj.isSubsequence01(s, t));
    }

    /**
     * 空间复杂度:o(1)
     * 时间复杂度:o(len(t)*len(s))
     *
     * @param s
     * @param t
     * @return
     */
    public boolean isSubsequence(String s, String t) {
        if (s == null || t == null) {
            return false;
        }

        int slen = s.length();
        int tlen = t.length();

        if (slen > tlen) {
            return false;
        }

        int starter = -1;
        int count = 0;
        for (int i = 0; i < slen; i++) {

            //如果目标串起始查询位置后剩余元素的个数小于子串未匹配串的长度
            //例如 s=bef,t=adcb
            if (slen - i > tlen - starter) {
                return false;
            }

            char cur = s.charAt(i);
            //同一元素不能匹配两次，因此，这里从 starter + 1 开始
            for (int j = starter + 1; j < tlen; j++) {
                if (t.charAt(j) == cur) {
                    count++;
                    starter = j;
                    break;
                }
            }
        }

        return count == slen;
    }

    /**
     * 双指针+贪心
     * 时间复杂度:O(m+n)
     * 空间复杂度:O(1)
     * @param s
     * @param t
     * @return
     */
    public boolean isSubsequence01(String s, String t) {
        int i = 0, j = 0;
        int slen = s.length();
        int tlen = t.length();

        while (i < slen && j < tlen) {
            if (s.charAt(i) == t.charAt(j)) {
                i++;
            }
            j++;
        }

        return i == slen;
    }
}
